import unittest
from billing import invoice_amount

class InvoiceAmountTests(unittest.TestCase):
    def test_formats_and_truncates_toward_zero(self):
        cases = {
            "12": "12.00",
            "12.3": "12.30",
            "12.349": "12.34",
            "-12.349": "-12.34",
            "0.009": "0.00",
            "+1.235": "1.23",
        }
        for value, expected in cases.items():
            with self.subTest(value=value):
                self.assertEqual(invoice_amount(value), expected)

    def test_rejects_invalid_values(self):
        for value in ("", "12.3.4", "NaN", "Infinity", "-Infinity"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    invoice_amount(value)

    def test_requires_string(self):
        for value in (12, 12.3, None):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    invoice_amount(value)

unittest.main()

